{"objects": [
  {
    "objectType": "Concept",
    "evidenceQuote": "她的智能之所以动人，是因为她拥有强大的**工具**——连接语言“大脑”与真实数字世界的“手脚和感官”。",
    "canonicalTerm": "工具",
    "aliases": [],
    "definition": "连接语言“大脑”与真实数字世界的“手脚和感官”。",
    "examples": ["科幻电影《Her》中 AI 助手 Samantha 能主动整理邮件、识别情感复杂的信件并提议润色回复、代表主角处理出版事宜", "Manus、OpenClaw 等通用 Agent"]
  },
  {
    "objectType": "Concept",
    "evidenceQuote": "工具生态用哪两条渠道分发能力——MCP 协议与 Skill Hub",
    "canonicalTerm": "工具生态",
    "aliases": [],
    "definition": "用 MCP 协议与 Skill Hub 两条渠道分发工具能力的生态。",
    "examples": ["MCP 协议", "Skill Hub"]
  }
]}

{
  "objects": [
    {
      "objectType": "Concept",
      "evidenceQuote": "Skill：用自然语言编写的 Skill 文档来描述操作流程，Agent 通过终端或代码解释器来执行，只需少量的通用工具就能覆盖大量场景；一份 skill 在目录里只占几十个 token，正文用到时才读。",
      "canonicalTerm": "Skill",
      "aliases": ["Skill 文档", "skill"],
      "definition": "用自然语言编写的 Skill 文档来描述操作流程，Agent 通过终端或代码解释器来执行，只需少量的通用工具就能覆盖大量场景；一份 skill 在目录里只占几十个 token，正文用到时才读。",
      "examples": [
        "一个“部署应用”的 Skill 文档可能写成 1. 运行 npm run build 构建项目；2. 运行 docker build -t app:latest . 打包镜像；3. 运行 kubectl apply -f deploy.yaml 部署到集群——Agent 通过 bash 工具逐步执行这些指令，无需为每个步骤创建专用工具。"
      ]
    },
    {
      "objectType": "Heuristic",
      "evidenceQuote": "默认取向：通用工具优于专用工具，除非存在明确的安全、权限或性能理由。",
      "trigger": "在决定一项能力应该做成专用工具还是通用工具/Skill时",
      "recommendation": "通用工具优于专用工具，除非存在明确的安全、权限或性能理由。",
      "confidence": 0.8,
      "exceptions": ["存在明确的安全、权限或性能理由"]
    }
  ]
}

{
  "objects": [
    {
      "objectType": "AntiPattern",
      "evidenceQuote": "工具在执行前悄悄地“修正”模型的输入参数，导致实际操作偏离了模型的意图。",
      "pattern": "静默输入转换：工具在执行前悄悄地“修正”模型的输入参数，导致实际操作偏离模型意图。",
      "harm": "模型读取到的内容与工具实际匹配或写入的内容不一致，导致替换操作返回“未找到匹配”，模型反复尝试、反复失败；写入方向文件内容被静默篡改，模型误以为已经写入符合中文排版规范的内容。",
      "corrective": "工具的参数传递必须保持透明，不得在模型不知情的情况下修改输入或输出；确需规范化时必须在工具描述中说明，并在工具返回中明确告知模型。",
      "evidence": [
        "Cursor 2026 年初的某个版本将中文弯引号静默转换为英文直引号，导致 old_string 与文件实际内容不匹配，工具返回“未找到匹配”，模型反复尝试、反复失败。",
        "写入方向模型本意写入弯引号，参数传递层静默替换为直引号，文件实际内容被篡改，模型验证写入结果时陷入困惑。"
      ]
    },
    {
      "objectType": "EngineeringRule",
      "evidenceQuote": "工具的参数传递必须保持透明，不得在模型不知情的情况下修改输入或输出。",
      "statement": "工具的参数传递必须保持透明，不得在模型不知情的情况下修改输入或输出。",
      "rationale": "模型依靠读取工具观察文件内容并据此构造参数，若工具静默修改输入或输出，模型感知到的世界与工具操作的世界之间会产生系统性偏差，形成模型无法自行诊断的故障。",
      "appliesWhen": "工具或平台在模型与底层操作之间传递参数、转换编码、规范化输入或执行命令时。",
      "violation": "工具在模型不知情的情况下修改输入或输出，例如静默替换引号、静默向 git commit 注入额外参数，导致工具行为偏离模型意图。"
    }
  ]
}

{"objects": [
  {
    "objectType": "Concept",
    "evidenceQuote": "答案有三层，一层比一层更“按需”。",
    "canonicalTerm": "按需工具暴露",
    "aliases": [],
    "definition": "当工具数量增长时，不把全部工具定义一次性暴露给模型，而是按执行需要动态加载、主动发现或以参考资料形式提供工具。",
    "examples": [
      "层次化组织与按需加载：工具定义事先备好，仅按需加载而不全量塞进上下文",
      "主动工具发现：Agent 在执行过程中意识到能力缺口，主动声明需求，由系统动态匹配并注入",
      "Skills：把工具当作可随手翻阅的参考资料，而非需要注册、检索、注入的正式定义"
    ]
  },
  {
    "objectType": "EngineeringRule",
    "evidenceQuote": "工具数量超过一百个时，即使最先进的大语言模型也容易在工具选择上出错；全部平铺进上下文还要占去大量 token，并让每一次工具集的变动都击穿 KV Cache。",
    "statement": "当可用工具数量超过一百个时，不应将全部工具定义全量平铺进上下文。",
    "rationale": "工具数量超过一百个会显著增加选择错误；全量平铺占用大量 token，工具集每次变动还会击穿 KV Cache。",
    "appliesWhen": "可用工具规模达到一百以上，或工具集变动频繁且上下文预算有限时。",
    "violation": "继续全量平铺工具定义，导致工具选择错误、上下文 token 消耗过大、KV Cache 频繁失效。"
  }
]}

{
  "objects": [
    {
      "objectType": "Concept",
      "evidenceQuote": "更进一步的思路，是让 Agent 从被动接受者变为主动发现者：在执行过程中意识到能力缺口时，主动用自然语言声明 “我需要什么能力”，系统再动态匹配并注入。",
      "canonicalTerm": "主动工具发现",
      "aliases": ["模型原生的主动工具发现", "工具主动发现"],
      "definition": "让 Agent 在执行过程中意识到能力缺口时，主动用自然语言声明所需能力，系统按语义匹配并动态注入对应工具，而非预置全部工具 schema。",
      "examples": [
        "MCP-Zero 在系统提示词中不预置任何工具 schema，Agent 生成结构化请求块，系统通过服务器级到工具级的两层语义路由匹配注入工具。",
        "Anthropic 在 Claude API 中提供的 Tool Search Tool，Agent 用自然语言描述需求即可检索并加载工具。",
        "实验组仅保留 web_search、code_interpreter 和 discover_tools 元工具，引导模型在遇到能力缺口时主动调用 discover_tools 获取候选工具。"
      ]
    },
    {
      "objectType": "AntiPattern",
      "evidenceQuote": "将所有 120+ 工具的完整 schema 一次性注入 system prompt（超 50K tokens）。4B 模型在这么长的上下文下指令遵循能力严重退化",
      "pattern": "在系统提示词中一次性注入所有工具的完整 schema",
      "harm": "小参数量模型在超长上下文下指令遵循能力严重退化，可能错选工具或忘记工具列表中的某些工具，导致任务失败。",
      "corrective": "采用主动工具发现混合方案，仅保留少量基础工具和 discover_tools 元工具，按需通过语义匹配动态注入工具 schema。",
      "evidence": [
        "对照组将所有 120+ 工具的完整 schema 一次性注入 system prompt，超 50K tokens，4B 模型指令遵循能力严重退化，出现错选 Web Search 而非 Yahoo Finance 工具或忘记工具列表中的某些工具等问题。"
      ]
    }
  ]
}

{"objects": [
  {
    "objectType": "Concept",
    "evidenceQuote": "Skills 则把渐进式披露作为默认的组织方式：Agent 启动时只看到一份薄薄的目录——每个 skill 的 `name` 与 `description`（合计数百 token）。当**当前上下文**真的需要某种能力时，模型才去读取对应的 sub-skill，并顺着其中的引用再往下一层，读取具体的脚本或子文档。",
    "canonicalTerm": "Skills",
    "aliases": [],
    "definition": "一种工具发现范式，默认采用渐进式披露：Agent 启动时只加载薄薄的技能目录，需要某种能力时再按需读取对应 sub-skill 与具体脚本或子文档，从而避免大规模工具定义常驻上下文。",
    "examples": ["同一个 skill 既可以躺在 Skill Hub 里等 npx 来装，也可以由一台 MCP 服务器供给。"]
  },
  {
    "objectType": "EngineeringRule",
    "evidenceQuote": "工具的详细定义不必全部常驻上下文，用到哪条查哪条。",
    "statement": "工具的详细定义不必全部常驻上下文，用到哪条查哪条。",
    "rationale": "没有人会把一本工具书或整个维基百科从第一页读到最后一页，而是顺着索引和目录，根据当下需要逐个查阅词条。",
    "appliesWhen": "当工具集规模较大，或需要避免完整工具 schema 一次性进入模型上下文时。",
    "violation": "在会话开始时把完整 schema 一次性摆在模型面前，而不是按需披露工具定义。"
  }
]}

{"objects": [
  {"objectType": "EngineeringRule", "evidenceQuote": "搜索工具的返回值应该是结构化的候选列表（标题、位置、摘要片段），而不是拼接后的全文——让 Agent 先浏览候选，再决定深入读取哪一条。", "statement": "搜索类工具的返回值应该是结构化的候选列表（标题、位置、摘要片段），而不是拼接后的全文。", "rationale": "让 Agent 先浏览候选再决定深入读取，避免一次性倾倒全部结果造成上下文过载。", "appliesWhen": "设计搜索类工具的返回格式时。", "violation": "返回拼接后的全文或一次性倾倒全部结果，未提供结构化候选和分页/游标参数。"},
  {"objectType": "EngineeringRule", "evidenceQuote": "read 类工具应支持 offset/limit 参数，按需读取大文件的指定片段。当内容超过阈值必须截断时，应明确标示截断情况：注明省略了多少内容、如何读取剩余部分", "statement": "read 类工具应支持 offset/limit 参数按需读取大文件片段；内容超过阈值必须截断时，应明确标示省略了多少内容以及如何读取剩余部分。", "rationale": "静默截断会让 Agent 误以为自己看到了全部内容，基于不完整信息做出错误判断。", "appliesWhen": "读取类工具处理大文件或输出超过阈值需要截断时。", "violation": "静默截断内容，未注明省略了多少内容或如何继续读取剩余部分。"}
]}

{
  "objects": [
    {
      "objectType": "Concept",
      "evidenceQuote": "其核心技术突破在于，通过专门的编码器将不同类型的数据全部映射到统一的高维语义空间。",
      "canonicalTerm": "原生多模态处理",
      "aliases": [],
      "definition": "能力上限最高的技术路线，通过专门的编码器将不同类型的数据全部映射到统一的高维语义空间，使模型可直接理解图像、文本等跨模态信息。",
      "examples": ["模型可以直接看到 PDF 的页面布局、图表和文字，并理解图文之间的空间和语义关系"]
    },
    {
      "objectType": "Concept",
      "evidenceQuote": "具体来说，ViT 将图像分割为固定大小的图像块（Patches），像处理句子中的单词一样将每个块序列化为向量，与文本词向量共存于共享的多模态嵌入空间。",
      "canonicalTerm": "Vision Transformer",
      "aliases": ["ViT"],
      "definition": "一种视觉编码器，将图像分割为固定大小的图像块（Patches），把每个块序列化为向量，并与文本词向量共存于共享的多模态嵌入空间。",
      "examples": ["Qwen-VL、LLaVA 等架构公开的多模态模型通常集成了基于 Vision Transformer（ViT）的视觉编码器"]
    }
  ]
}

{"objects": [
  {
    "objectType": "Concept",
    "evidenceQuote": "当 Agent 的主模型不支持多模态时，**将多模态分析作为工具**是一种比提取为文本更好的方法。",
    "canonicalTerm": "工具化多模态分析",
    "aliases": ["工具化模式"],
    "definition": "当 Agent 的主模型不支持多模态时，将多模态分析封装为工具，通过接受多模态文件和自然语言问题并返回自然语言描述的分析结果，使 Agent 能对原始文件进行深入分析。",
    "examples": ["使用 analyze_image 分析图片并返回自然语言描述", "使用 analyze_pdf 分析含图表的 PDF 报告"]
  },
  {
    "objectType": "Heuristic",
    "evidenceQuote": "**工具化模式**在交互式场景中展现灵活性，能以较低成本处理大多数初步查询并在需要时通过调用工具进行高成本深度分析，但在需要一次性端到端深度理解的场景下表现不如原生模式。",
    "trigger": "当 Agent 的主模型不支持多模态，但又需要处理多模态文件时",
    "recommendation": "将多模态分析作为工具提供，仅在上下文中保留简短问题与分析结果，避免多模态数据占据大量 token",
    "confidence": 0.7,
    "exceptions": ["在需要一次性端到端深度理解的场景下表现不如原生模式"]
  }
]}

{"objects": [
  {
    "objectType": "MentalModel",
    "evidenceQuote": "提议者-审核者（Proposer-Reviewer）范式——用独立的第二视角检验第一视角的产出——应用于安全审查场景时，有两种典型机制：**事前审批**与**事后验证**。",
    "trigger": "对于不可逆的关键操作，需要更智能的审查机制时",
    "inputs": ["提议模型生成的行动方案", "审批模型的风险评估与批准", "双方共用的底层规则与上下文"],
    "reasoning": "独立第二视角引入认知多样性，降低单一模型的决策错误率；审批模型与提议模型能力相近但训练偏好不同，可在不同盲区互相校验。",
    "limits": "两个模型能力相差过大时审批模型可能跟不上提议模型的思考，审查不可靠；若两模型来自同一家族，训练数据与偏好相似，容易在相同场景犯相同错误。",
    "counterexample": "两个模型都来自同一家族（如都是 GPT）时，容易在相同场景共同犯错；用 Haiku 审查 Opus 的输出因能力差距过大而不可靠。"
  },
  {
    "objectType": "EngineeringRule",
    "evidenceQuote": "Python 虚拟环境（venv）不是沙盒。它只隔离包依赖，对文件系统、网络和进程没有任何安全约束，在 venv 中运行的代码照样可以删除任意文件、访问任意网络。",
    "statement": "Python 虚拟环境（venv）不是沙盒，不能提供文件系统、网络和进程隔离。",
    "rationale": "venv 只隔离包依赖，对文件系统、网络和进程没有任何安全约束。",
    "appliesWhen": "使用 Python 虚拟环境运行不可信代码，或期望获得安全隔离时。",
    "violation": "在 venv 中运行不可信代码时，代码仍可删除任意文件、访问任意网络。"
  }
]}

